t=np.arange(180);rng=np.random.default_rng(15);common=np.cumsum(rng.normal(0,.012,180));s=np.zeros(180);[s.__setitem__(i,.88*s[i-1]+rng.normal(0,.018)) for i in range(1,180)];a=common+s;b=common*.95;ax.plot(t,np.exp(a)*100,color=ACCENT,label='Asset A');ax.plot(t,np.exp(b)*100,color=WARM,label='Asset B');ax.set_xlabel('trading day');ax.set_ylabel('synthetic price (USD)');ax.legend(fontsize=8);ax.set_title('Common trend alone is not the trading signal',loc='left')
